import{_ as e,o as a,c as d,a6 as r}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"从单图到一套商品图","description":"","frontmatter":{"id":"image-set","title":"从单图到一套商品图","chapter":"03","status":"已公开","evidence_status":"方法已整理，未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["rembg","birefnet","footwear-skills","ecommerce-skills"],"order":21},"headers":[],"relativePath":"ecommerce/image-set.md","filePath":"ecommerce/image-set.md"}'),i={name:"ecommerce/image-set.md"};function o(s,t,l,c,n,m){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="从单图到一套商品图" tabindex="-1">从单图到一套商品图 <a class="header-anchor" href="#从单图到一套商品图" aria-label="Permalink to &quot;从单图到一套商品图&quot;">​</a></h1><p>以真实商品图和事实表为输入，先分配图片职责，再安排风格一致性。一套图片的数量按渠道和商品任务确定，下面的“1＋5”是练习结构。</p><table tabindex="0"><thead><tr><th>图片</th><th>解决的问题</th><th>必须核对</th></tr></thead><tbody><tr><td>1 主图</td><td>买家一眼识别商品</td><td>主体真实、发货内容、渠道要求</td></tr><tr><td>2 场景</td><td>在哪里使用</td><td>大小关系、道具是否误导</td></tr><tr><td>3 细节</td><td>材质与关键结构</td><td>原图依据、没有补假结构</td></tr><tr><td>4 尺寸</td><td>是否合适</td><td>真实参数、单位、标注</td></tr><tr><td>5 使用</td><td>怎么操作</td><td>顺序和动作符合实际</td></tr><tr><td>6 信任信息</td><td>为什么可信</td><td>证明材料与准确文案</td></tr></tbody></table><h2 id="制作步骤" tabindex="-1">制作步骤 <a class="header-anchor" href="#制作步骤" aria-label="Permalink to &quot;制作步骤&quot;">​</a></h2><ol><li>按<a href="/ai-visual-creation-handbook/ecommerce/product-brief">商品简报</a>整理SKU与实拍。</li><li>为每张图写一张任务卡，共用主体、色彩与字体，分别写构图和准确文字。</li><li>使用<a href="/ai-visual-creation-handbook/prompts/P01">P01</a>先完成场景图，检查商品身份后再扩展。</li><li>细节和尺寸图以真实照片与数据为底，准确文字用图层排版；需要改一处时使用<a href="/ai-visual-creation-handbook/prompts/P06">P06</a>。</li><li>在<a href="/ai-visual-creation-handbook/workflows/canvases">三类画布</a>中分离候选、通过和返工版本。</li><li>逐图检查，再检查整套一致性；导出文件名包含SKU、用途、语言与版本。</li></ol><p>图像模型生成的细节放大不等于真实微观结构。证据图、检测报告和认证标识使用真实授权原件，不生成替代。</p>',6)])])}const p=e(i,[["render",o]]);export{_ as __pageData,p as default};
